# Define the laws for reanalysis
def gravitational_law(G, m1, m2, r):
    """Gravitational law: F = G * m1 * m2 / r^2."""
    return G * (m1 * m2) / (r ** 2)

def hookes_law(k, x):
    """Hooke's law: F = -k * x."""
    return -k * x

def kinetic_energy(m, v):
    """Kinetic energy: KE = 0.5 * m * v^2."""
    return 0.5 * m * (v ** 2)

# Parameters for laws
laws = {
    "Gravitational Law": {
        "function": gravitational_law,
        "parameters": {"G": 6.67430e-11, "m1": 5.972e24, "m2": 7.348e22, "r": [1e6, 1e7, 1e8]},
        "variable": "r"
    },
    "Hooke's Law": {
        "function": hookes_law,
        "parameters": {"k": 100, "x": [0.1, 0.2, 0.3, 0.4]},
        "variable": "x"
    },
    "Kinetic Energy": {
        "function": kinetic_energy,
        "parameters": {"m": 1, "v": [10, 20, 30, 40]},
        "variable": "v"
    }
}

# Apply the formula and calculate errors for each law
def test_law(name, law):
    results = []
    function = law["function"]
    params = law["parameters"]
    variable = law["variable"]

    for value in params[variable]:
        # Expected value from the law
        expected = function(**{k: v for k, v in params.items() if k != variable}, **{variable: value})

        # Computed value from the current formula
        computed = earlier_formula(value, 20, 0.35)

        # Error calculation
        error = abs((computed - expected) / expected) * 100 if expected != 0 else 0
        results.append({
            "Variable": value,
            "Expected": expected,
            "Computed": computed,
            "Error (%)": error
        })
    return name, results

# Reanalyze all laws
reanalysis_results = {}
for name, law in laws.items():
    law_name, results = test_law(name, law)
    reanalysis_results[law_name] = results

# Summarize results for all laws
import pandas as pd
import ace_tools as tools

combined_results = []
for law_name, results in reanalysis_results.items():
    for result in results:
        combined_results.append({"Law": law_name, **result})

combined_results_df = pd.DataFrame(combined_results)

tools.display_dataframe_to_user("Reanalysis of All Laws for Deviations", combined_results_df)

